-- 팝업관리(메뉴 1311) 검증용 시드 20건
--
-- admin.op_popup이 0행이라 목록·검색·페이징·선택삭제를 확인할 수 없었다.
-- AS-IS 코드값 그대로 쓴다:
--   popup_close  1=사용 / 2=일시정지 / 3=종료      (AS-IS M00083 / M00732 / M00733)
--   popup_type   1=윈도우 / 2=레이어              (M00747 / M00748)
--   popup_style  1=텍스트입력 / 3=이미지등록      (M00736 / M00738, 2=테두리없음은 AS-IS도 주석)
--   start/end_date는 yyyyMMdd 문자열, start/end_time은 시(2자리) - AS-IS가 문자열로 비교한다.
--
-- 검색 확인 분포: 상태 1=10건 / 2=5건 / 3=5건, 형태 1=14건 / 3=6건, 타입 1=12건 / 2=8건.
-- 제목 LIKE 확인용으로 '점검'(4건)·'이벤트'(5건)·'안내'(6건)를 섞어 두었다.

insert into admin.op_popup
       (popup_close, popup_type, popup_style, subject, content,
        start_date, start_time, end_date, end_time,
        width, height, top_position, left_position, popup_image, image_link, use_yn, created_date)
